import { Lightbulb, RefreshCw } from 'lucide-react'
import { useCallback, useEffect, useRef, useState } from 'react'
import { generateQuestions, getStoredQuestions } from '../lib/api'
import { useApp } from '../state/AppContext'
import { ErrorBanner, Spinner } from './ui'

interface Props {
  documentId?: string          // undefined = whole workspace
  disabled?: boolean           // e.g. nothing ready yet
  onPick: (q: string) => void
}

/** Questions are generated by the selected model FROM the document text and filtered for answerability on the server. */
export default function SuggestedQuestions({ documentId, disabled, onPick }: Props) {
  const { workspaceId, provider, model, providerProblem } = useApp()
  const [questions, setQuestions] = useState<string[]>([])
  const [loading, setLoading] = useState(false)
  const [note, setNote] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const attempted = useRef(new Set<string>())
  const scopeKey = `${workspaceId}:${documentId ?? ''}`

  const generate = useCallback(async () => {
    setLoading(true); setError(null); setNote(null)
    try {
      const r = await generateQuestions(workspaceId, { document_id: documentId, count: 5, provider, model })
      setQuestions(r.all)
      if (!r.questions.length) setNote('No new questions could be generated from the document this time.')
    } catch (e) { setError((e as Error).message) }
    finally { setLoading(false) }
  }, [workspaceId, documentId, provider, model])

  useEffect(() => {
    let cancelled = false
    setQuestions([]); setNote(null); setError(null)
    if (disabled) return
    getStoredQuestions(workspaceId, documentId ?? '').then(r => {
      if (cancelled) return
      setQuestions(r.questions)
      // auto-generate once per scope, only if a working provider is selected
      if (!r.questions.length && !attempted.current.has(scopeKey) && !providerProblem) {
        attempted.current.add(scopeKey)
        void generate()
      }
    }).catch(() => undefined)
    return () => { cancelled = true }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scopeKey, disabled])

  if (disabled) return null
  return (
    <section aria-label="Suggested questions" className="rounded-2xl border border-white/10 bg-white/[0.03] p-4">
      <div className="mb-3 flex items-center justify-between">
        <h3 className="flex items-center gap-2 text-sm font-semibold text-white"><Lightbulb className="h-4 w-4 text-amber-300" />Suggested Questions</h3>
        <button className="btn-ghost px-3 py-1.5 text-xs" onClick={() => void generate()} disabled={loading || !!providerProblem} title={providerProblem ?? ''}>
          {loading ? <Spinner className="h-3 w-3" /> : <RefreshCw className="h-3 w-3" />}{questions.length ? 'Generate More' : 'Generate Questions'}
        </button>
      </div>
      {questions.length > 0 && (
        <div className="grid gap-2 sm:grid-cols-2">
          {questions.map(q => (
            <button key={q} type="button" onClick={() => onPick(q)}
              className="rounded-xl border border-white/10 bg-ink-900/60 px-3 py-2 text-left text-sm text-slate-200 transition hover:border-accent-soft hover:bg-accent/10">{q}</button>
          ))}
        </div>
      )}
      {!questions.length && !loading && !error && <p className="text-sm text-slate-500">{providerProblem ? 'Select a working model to generate questions.' : 'No questions yet.'}</p>}
      {loading && !questions.length && <p className="text-sm text-slate-400">Reading the document and writing questions…</p>}
      {note && <p className="mt-2 text-xs text-slate-500">{note}</p>}
      {error && <div className="mt-2"><ErrorBanner onClose={() => setError(null)}>{error}</ErrorBanner></div>}
    </section>
  )
}
